-- Touches: iam.tenants, iam.memberships, iam.tenant_legal_profiles
-- 8-B (2026-10-11): KI-05 — onboarding RPCs removed; tenants.status has no 'provisioning' (default 'active').
-- Promoted from _drafts/006_iam_create_tenant_onboarding.sql
